#!/usr/bin/env bash
# Smoke test: pgbouncer starts, authenticates (md5 userlist generated by the
# entrypoint) and proxies a query to a real Postgres.
# Usage: test/smoke.sh <image>
set -euo pipefail

IMAGE="${1:?usage: $0 <image>}"
SUFFIX="$$"
NET="pgb-smoke-${SUFFIX}"
DB="pgb-smoke-db-${SUFFIX}"
PGB="pgb-smoke-pgb-${SUFFIX}"
USER_NAME=drupal
USER_PASS=smoke-test-pass
WORKDIR="$(mktemp -d)"

cleanup() {
  status=$?
  if [ "$status" -ne 0 ]; then
    echo "--- pgbouncer logs" >&2
    docker logs "$PGB" >&2 2>&1 || true
  fi
  docker rm -f "$PGB" "$DB" >/dev/null 2>&1 || true
  docker network rm "$NET" >/dev/null 2>&1 || true
  rm -rf "$WORKDIR"
  exit "$status"
}
trap cleanup EXIT

cat > "$WORKDIR/pgbouncer.ini" <<INI
[databases]
* = host=${DB} pool_size=5

[pgbouncer]
listen_addr = *
listen_port = 6432
unix_socket_dir =
pidfile =
auth_type = md5
auth_file = /etc/pgbouncer/userlist.txt
INI

docker network create "$NET" >/dev/null

# The chart uses md5 auth, so the backing database must store md5 hashes.
docker run -d --name "$DB" --network "$NET" \
  -e POSTGRES_USER="$USER_NAME" -e POSTGRES_PASSWORD="$USER_PASS" -e POSTGRES_DB=drupal \
  -e POSTGRES_HOST_AUTH_METHOD=md5 -e POSTGRES_INITDB_ARGS="--auth-host=md5" \
  postgres:16-alpine -c password_encryption=md5 >/dev/null

docker run -d --name "$PGB" --network "$NET" \
  -v "$WORKDIR/pgbouncer.ini:/etc/pgbouncer/pgbouncer.ini:ro" \
  -e DRUPAL_DB_USER="$USER_NAME" -e DRUPAL_DB_PASSWORD="$USER_PASS" \
  -e PGHOST="$DB" -e PGDATABASE=drupal -e PGUSER="$USER_NAME" -e PGPASSWORD="$USER_PASS" \
  "$IMAGE" >/dev/null

query() { # <password>
  docker exec -e PGPASSWORD="$1" "$PGB" \
    psql -h 127.0.0.1 -p 6432 -U "$USER_NAME" -d drupal -tA -c 'select 1'
}

echo "waiting for pgbouncer to proxy a query..."
for _ in $(seq 1 60); do
  if [ "$(query "$USER_PASS" 2>/dev/null || true)" = "1" ]; then
    ok=1
    break
  fi
  sleep 1
done
[ "${ok:-0}" = "1" ] || { echo "FAIL: no query through pgbouncer succeeded" >&2; exit 1; }
echo "ok: select 1 through pgbouncer with md5 auth"

if query "wrong-password" >/dev/null 2>&1; then
  echo "FAIL: pgbouncer accepted a wrong password" >&2
  exit 1
fi
echo "ok: wrong password rejected"

[ "$(docker inspect -f '{{.State.Running}}' "$PGB")" = "true" ] \
  || { echo "FAIL: pgbouncer exited" >&2; exit 1; }
echo "smoke test passed"
